#!/usr/bin/env python3
"""Close and import the original regional HGSS Cerulean nonenterable house."""
import argparse,copy,hashlib,json
from pathlib import Path,PurePosixPath
from import_hgss_center import archive_items
from import_pallet_buildings import extract
from import_scenery_models import normalize
from import_oras_grass import lua
from scenery_closures import hull
ID='hgss_cerulean_closed_house'
URL='https://models.spriters-resource.com/ds_dsi/pokemonheartgoldsoulsilver/asset/592833/'
def close_house(parts):
 source=next(p for p in parts if p['texture']=='hdc_h01b.png');out=[]
 def part(name):
  p={k:copy.deepcopy(v)for k,v in source.items()if k!='vertices'};p.update(name='authored_'+name,vertices=[],authored=True,role='structure');out.append(p);return p
 def poly(p,pts,uv):
  for i in range(1,len(pts)-1):p['vertices'].extend([list(pts[j])+list(uv[j])+[1.]for j in(0,i,i+1)])
 left,right=-27.90625,27.89258
 p=part('rear_siding');poly(p,[(left,2,-24),(right,2,-24),(right,33,-24),(left,33,-24)],[(.1103515,.984375),(.1103515,.984375),(.1103515,.5),(.1103515,.5)])
 p=part('rear_beam');poly(p,[(left,33,-27),(right,33,-27),(right,38,-27),(left,38,-27)],[(.9482422,.5166016),(.9482422,.5166016),(.9482422,.5058594),(.9482422,.5058594)])
 p=part('rear_beam_return');poly(p,[(left,33,-27),(left,33,-24),(right,33,-24),(right,33,-27)],[(.9482422,.51)]*4)
 p=part('rear_inner_gable');poly(p,[(left,38,-27),(right,38,-27),(19,45.98242,-27),(-19,45.98242,-27)],[(.1103515,.5)]*4)
 p=part('rear_roof_fascia')
 for i in range(0,len(source['vertices']),3):
  t=source['vertices'][i:i+3]
  if all(abs(v[2]-18)<1e-6 for v in t)and min(v[1]for v in t)>=37.53516-1e-6 and(min(v[1]for v in t)>=45.98242-1e-6 or max(abs(v[0])for v in t)>28.125):
   for v in reversed(t):q=list(v);q[2]-=46;p['vertices'].append(q)
 assert len(p['vertices'])==24,'original roof fascia changed'
 p=part('roof_soffit');profile=[(-28.125,37.53516),(-19,45.98242),(19,45.98242),(28.125,37.53516)]
 for a,b in zip(profile,profile[1:]):poly(p,[(a[0],a[1],-28),(a[0],a[1],18),(b[0],b[1],18),(b[0],b[1],-28)],[(.9482422,.51)]*4)
 p=part('closed_foundation');outline=hull([v for a in parts for v in a['vertices']if abs(v[1]-2)<1e-6]);poly(p,[(x,1.95,z)for x,z in reversed(outline)],[(.1103515,.99)]*len(outline))
 for i,a in enumerate(outline):
  b=outline[(i+1)%len(outline)];poly(p,[(a[0],1.95,a[1]),(b[0],1.95,b[1]),(b[0],2,b[1]),(a[0],2,a[1])],[(.1103515,.99)]*4)
 return out

def convert(archive,output):
 blob=archive.read_bytes();items,repairs=archive_items(blob);source=next(n for n in items if n.endswith('.dae'));raw=items[source]
 parts=extract(raw,{ID:'ha_h01b-mesh'}, {})[ID];original=copy.deepcopy(parts);parts=[p for p in parts if p['role']!='source_shading'];parts.extend(close_house(parts));meta=normalize(parts);original_meta=normalize(original)
 folder=output/'assets/scenery/cerulean-closed-house';folder.mkdir(parents=True,exist_ok=True);names={PurePosixPath(n).name:n for n in items};textures={}
 for p in parts:
  name=p['texture'];b=items[names[name]];(folder/name).write_bytes(b);textures[name]={'sha256':hashlib.sha256(b).hexdigest(),'bytes':len(b)};p['texture']='assets/scenery/cerulean-closed-house/'+name
 data={ID:{'parts':parts,'bounds':meta['bounds']}}
 report={'asset':592833,'sourcePage':URL,'title':'Cerulean closed regional house','game':'Pokémon HeartGold / SoulSilver','originalGameArt':'Nintendo / Creatures / GAME FREAK','archiveSha256':hashlib.sha256(blob).hexdigest(),'sourceFile':source,'sourceModelSha256':hashlib.sha256(raw).hexdigest(),'geometry':'ha_h01b-mesh','containerRepairs':repairs,'normalization':meta,'originalBounds':original_meta['sourceBounds'],'originalTriangles':sum(p['triangles']for p in original),'processedTriangles':sum(p['triangles']for p in parts),'closure':'Continue measured rear olive siding/cyan plinth and brown beam, inset plain gable, exact original roof fascia copied to the rear cut, profiled roof soffit and recessed foundation. No new windows, vents, door or signs; original physical triangles/UV/PNG bytes retained, source shadows excluded.','textures':textures,'parts':[{'name':p['name'],'role':p['role'],'authored':p.get('authored',False),'triangles':p['triangles']}for p in parts]}
 (folder/'provenance.json').write_text(json.dumps(report,indent=2,ensure_ascii=False)+'\n');(output/'lib').mkdir(parents=True,exist_ok=True);(output/'lib/CeruleanClosedHouseData.lua').write_text('-- Generated by tools/import_cerulean_closed_house.py; original attribution beside textures.\nreturn '+lua(data)+'\n');return data,report
if __name__=='__main__':
 p=argparse.ArgumentParser();p.add_argument('archive',type=Path);p.add_argument('output',type=Path);a=p.parse_args();_,r=convert(a.archive,a.output);print(ID,r['originalTriangles'],r['processedTriangles'])
